// ===========================================================================
// LINKA Catalog seed  (MongoDB)  ->  database: LinkaCatalogDb
// 12 categories x 20 products = 240 products (+ ProductDetails + ProductImages)
//
// HOW TO RUN:
//   mongosh "mongodb://localhost:27017/LinkaCatalogDb" linka_seed.js
//   (or paste into MongoDB Compass > mongosh tab while LinkaCatalogDb is open)
//
// Categories are matched by name: existing ones are reused (no duplicates),
// missing ones are created. Re-running ADDS another 240 products, so clear
// first if you want a fresh set (see the optional block below).
// ===========================================================================

db = db.getSiblingDB("LinkaCatalogDb");

// --- OPTIONAL: wipe catalog before seeding (uncomment the 4 lines) ----------
 //db.Products.deleteMany({});
 //db.ProductDetails.deleteMany({});
 //db.ProductImages.deleteMany({});
 //db.Categories.deleteMany({});

// Reliable hex string for an ObjectId across mongosh / legacy shell:
function hex(oid){ return oid.toHexString ? oid.toHexString() : (oid.str || String(oid)); }

// 1) Ensure categories exist, capture their _id ------------------------------
var categoryImages = {
  "Computers": "https://picsum.photos/seed/cat-computers/600/400",
  "Clothing": "https://picsum.photos/seed/cat-clothing/600/400",
  "Furniture": "https://picsum.photos/seed/cat-furniture/600/400",
  "Books": "https://picsum.photos/seed/cat-books/600/400",
  "Phones": "https://picsum.photos/seed/cat-phones/600/400",
  "Monitors": "https://picsum.photos/seed/cat-monitors/600/400",
  "Headphones": "https://picsum.photos/seed/cat-headphones/600/400",
  "Shoes": "https://picsum.photos/seed/cat-shoes/600/400",
  "Kitchen Utensils": "https://picsum.photos/seed/cat-kitchen-utensils/600/400",
  "Vegetables": "https://picsum.photos/seed/cat-vegetables/600/400",
  "Fruits": "https://picsum.photos/seed/cat-fruits/600/400",
  "Chocolates": "https://picsum.photos/seed/cat-chocolates/600/400"
};
var catIds = {};
Object.keys(categoryImages).forEach(function(name){
  var existing = db.Categories.findOne({ CategoryName: name });
  if (existing) { catIds[name] = existing._id; }
  else {
    var r = db.Categories.insertOne({ CategoryName: name, ImageUrl: categoryImages[name] });
    catIds[name] = r.insertedId;
  }
});
print("Categories ready: " + Object.keys(catIds).length);

